SELECT id, signal_id, execution_key, side, quantity, price_usdt, decision_price_usdt, execution_price_observed_at, UNIX_TIMESTAMP(execution_price_observed_at) AS obs_epoch, executed_at, UNIX_TIMESTAMP(executed_at) AS exec_epoch, gross_amount_usdt, fee_usdt, realized_pnl_usdt, execution_type, execution_reason, status FROM crypto_ai.wallet_trade WHERE signal_id IN (156723,159408,165412,167668,171589,176710,168277) OR execution_key REGEXP '^POSITION:(166|171|172|187|191|201|211):' ORDER BY executed_at LIMIT 40;